(ns armstrong-numbers) (defn exp [number n] (reduce * (repeat n number))) (defn armMap "Takes a number and returns a destructured sequence of it's integers" [number] (def size (count (str number))) (->> number (str) (partition 1) (flatten) (map #(Character/digit % 10)) (map #(exp % size)) (reduce +)) ) (defn armstrong? "Determine if a given number is an Armstrong number" [number] (== number (armMap number)) )
